import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Kebijakan Privasi","description":"","frontmatter":{},"headers":[],"relativePath":"kebijakan-privasi.md","filePath":"kebijakan-privasi.md"}`),a={name:`kebijakan-privasi.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="kebijakan-privasi" tabindex="-1">Kebijakan Privasi <a class="header-anchor" href="#kebijakan-privasi" aria-label="Permalink to “Kebijakan Privasi”">​</a></h1><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to “1. Introduction”">​</a></h2><p>Mikazuki AI (&quot;we&quot;, &quot;us&quot;, &quot;our&quot;) is an AI character interaction platform operated by <strong>Rafiq8K Studio</strong>. We are committed to protecting your privacy and handling your personal information responsibly.</p><p>This Privacy Policy explains what information we collect, how we use it, and your rights regarding your data.</p><hr><h2 id="_2-information-we-collect" tabindex="-1">2. Information We Collect <a class="header-anchor" href="#_2-information-we-collect" aria-label="Permalink to “2. Information We Collect”">​</a></h2><p>We collect only the information necessary to provide and maintain our service.</p><h3 id="_2-1-information-you-provide-during-registration" tabindex="-1">2.1 Information You Provide During Registration <a class="header-anchor" href="#_2-1-information-you-provide-during-registration" aria-label="Permalink to “2.1 Information You Provide During Registration”">​</a></h3><ul><li><strong>Email address</strong> — used for account identification, OTP verification, and password reset.</li><li><strong>Name / Display name</strong> — shown in your profile.</li><li><strong>Password</strong> — encrypted before reaching our servers. We never store passwords in plain text.</li></ul><h3 id="_2-2-information-collected-automatically" tabindex="-1">2.2 Information Collected Automatically <a class="header-anchor" href="#_2-2-information-collected-automatically" aria-label="Permalink to “2.2 Information Collected Automatically”">​</a></h3><ul><li><strong>Device information</strong> — device ID, model, brand, OS version, platform (collected only during ban events for enforcing bans).</li><li><strong>Activity data</strong> — anonymous usage statistics for internal analytics (e.g., number of active users).</li></ul><h3 id="_2-3-information-stored-locally-on-your-device-not-sent-to-our-servers" tabindex="-1">2.3 Information Stored Locally on Your Device (Not Sent to Our Servers) <a class="header-anchor" href="#_2-3-information-stored-locally-on-your-device-not-sent-to-our-servers" aria-label="Permalink to “2.3 Information Stored Locally on Your Device (Not Sent to Our Servers)”">​</a></h3><p>The following data remains on your device and is <strong>not</strong> collected or stored by us:</p><ul><li>Your <strong>chat history</strong> with AI characters</li><li>Your <strong>persona / roleplay identity</strong></li><li>Your <strong>API keys</strong> (used for Bring Your Own Key mode)</li><li>Your <strong>app preferences</strong> (theme, language, AI parameters, wallpaper, etc.)</li><li>Your <strong>app lock PIN</strong> (SHA-256 hashed)</li><li>Your <strong>chat summaries and memories</strong></li></ul><p>We do not upload, store, or process this data on our servers beyond what is required for real-time AI inference (see Section 4).</p><h3 id="_2-4-user-generated-content-fan-creations-submissions" tabindex="-1">2.4 User-Generated Content (Fan Creations &amp; Submissions) <a class="header-anchor" href="#_2-4-user-generated-content-fan-creations-submissions" aria-label="Permalink to “2.4 User-Generated Content (Fan Creations &amp; Submissions)”">​</a></h3><p>When submitting custom characters to our Cloud library:</p><ul><li><strong>Character metadata</strong> (name, description, personality, sample dialogs) is stored on our servers for moderation and cataloging.</li><li><strong>Images</strong> are automatically sanitized, stripped of all metadata (including camera and GPS tags), and re-encoded to WebP.</li><li><strong>IP addresses</strong> are cryptographically hashed with a keyed HMAC before storage to preserve your privacy while detecting abuse. Raw IP addresses are never retained.</li></ul><hr><h2 id="_3-how-we-use-your-information" tabindex="-1">3. How We Use Your Information <a class="header-anchor" href="#_3-how-we-use-your-information" aria-label="Permalink to “3. How We Use Your Information”">​</a></h2><p>We use the information we collect for the following purposes:</p><ol><li><strong>Account management</strong> — creating and maintaining your account, verifying your email, processing password resets.</li><li><strong>AI chat processing</strong> — transmitting your chat messages to third-party AI providers for real-time inference. Messages are processed ephemerally and are not stored by us.</li><li><strong>Security</strong> — detecting and preventing abuse, enforcing bans, monitoring for suspicious activity.</li><li><strong>Communication</strong> — sending you transactional emails (OTP verification, password reset).</li><li><strong>Analytics</strong> — understanding aggregate usage patterns to improve the service. This data is anonymous and cannot be traced back to you.</li></ol><p>We <strong>never</strong> use your data for advertising, profiling, or any purpose beyond what is explicitly described here.</p><hr><h2 id="_4-data-sharing-third-parties" tabindex="-1">4. Data Sharing &amp; Third Parties <a class="header-anchor" href="#_4-data-sharing-third-parties" aria-label="Permalink to “4. Data Sharing &amp; Third Parties”">​</a></h2><p>We do <strong>not</strong> sell, rent, or trade your personal information to third parties.</p><p>We share data only where necessary to provide the service:</p><table tabindex="0"><thead><tr><th>Third Party</th><th>Purpose</th><th>Data Shared</th></tr></thead><tbody><tr><td><strong>AI Providers</strong> (Google Gemini, Anthropic Claude, Mistral AI, NVIDIA NIM, etc.)</td><td>Process AI chat responses</td><td>Your chat messages (processed in real time, not stored)</td></tr><tr><td><strong>Brevo</strong></td><td>Send verification and password reset emails</td><td>Your email address</td></tr><tr><td><strong>Trakteer</strong></td><td>Process donations (VIP)</td><td>Your Trakteer transaction ID (no financial data handled by us)</td></tr><tr><td><strong>Discord</strong></td><td>Community support and child safety alerts</td><td>Anonymized alert information (only in case of policy violations)</td></tr><tr><td><strong>Cloudflare</strong></td><td>CDN, DNS, DDoS protection</td><td>Standard connection metadata (IP address)</td></tr></tbody></table><p>All third-party providers have their own privacy policies governing the use of your data. We encourage you to review them.</p><hr><h2 id="_5-data-retention" tabindex="-1">5. Data Retention <a class="header-anchor" href="#_5-data-retention" aria-label="Permalink to “5. Data Retention”">​</a></h2><table tabindex="0"><thead><tr><th>Data Type</th><th>Retention Period</th></tr></thead><tbody><tr><td><strong>Chat messages, persona, API keys, app preferences</strong></td><td>Stored locally on your device — you control this data. Delete the app or clear app data to remove it.</td></tr><tr><td><strong>Account data</strong> (email, name, password hash)</td><td>Until you request account deletion</td></tr><tr><td><strong>Activity logs</strong></td><td>Up to 1 year (aggregated and anonymized after analysis)</td></tr><tr><td><strong>Verification OTPs</strong></td><td>15 minutes (deleted after use or expiry)</td></tr></tbody></table><p>You may request account deletion at any time by contacting <strong><a href="mailto:support@r8kstudio.net" target="_blank" rel="noreferrer">support@r8kstudio.net</a></strong>. Upon deletion, all account data is permanently removed.</p><hr><h2 id="_6-data-security" tabindex="-1">6. Data Security <a class="header-anchor" href="#_6-data-security" aria-label="Permalink to “6. Data Security”">​</a></h2><p>We take reasonable precautions to protect your data:</p><ul><li>Passwords are <strong>bcrypt-hashed</strong> before storage.</li><li>Account access is secured via <strong>JWT tokens</strong> with 30-day expiry.</li><li>Your optional app lock PIN is <strong>SHA-256 hashed</strong> and stored only on your device.</li><li>Backup files can be <strong>AES-256-CBC encrypted</strong> for additional protection.</li></ul><p>However, no method of transmission or storage is 100% secure. We cannot guarantee absolute security.</p><hr><h2 id="_7-your-rights" tabindex="-1">7. Your Rights <a class="header-anchor" href="#_7-your-rights" aria-label="Permalink to “7. Your Rights”">​</a></h2><p>You have the following rights regarding your personal information:</p><ul><li><strong>Access</strong> — request a copy of the data we hold about you.</li><li><strong>Update</strong> — update your email, name, or password through the app.</li><li><strong>Delete</strong> — request deletion of your account and associated data by emailing <strong><a href="mailto:support@r8kstudio.net" target="_blank" rel="noreferrer">support@r8kstudio.net</a></strong>.</li><li><strong>Export</strong> — create a local backup of your chat data from within the app.</li><li><strong>Withdraw consent</strong> — stop using the service at any time.</li></ul><p>To exercise any of these rights, contact us at <strong><a href="mailto:support@r8kstudio.net" target="_blank" rel="noreferrer">support@r8kstudio.net</a></strong>. We will respond within 30 days.</p><hr><h2 id="_8-children-s-privacy" tabindex="-1">8. Children&#39;s Privacy <a class="header-anchor" href="#_8-children-s-privacy" aria-label="Permalink to “8. Children&#39;s Privacy”">​</a></h2><p>Mikazuki AI is <strong>not intended for users under the age of 16</strong>. We do not knowingly collect personal information from children under 16.</p><p>If we become aware that a user under 16 has created an account, we will delete their data and suspend the account immediately.</p><hr><h2 id="_9-international-data-transfers" tabindex="-1">9. International Data Transfers <a class="header-anchor" href="#_9-international-data-transfers" aria-label="Permalink to “9. International Data Transfers”">​</a></h2><p>Our servers are located in <strong>Indonesia</strong>. AI providers we integrate with may operate servers in various countries. By using Mikazuki AI, you consent to the transfer of your data to these locations for processing.</p><p>We ensure that all third-party providers we work with maintain adequate data protection standards.</p><hr><h2 id="_10-changes-to-this-privacy-policy" tabindex="-1">10. Changes to This Privacy Policy <a class="header-anchor" href="#_10-changes-to-this-privacy-policy" aria-label="Permalink to “10. Changes to This Privacy Policy”">​</a></h2><p>We may update this Privacy Policy from time to time. Material changes will be communicated via:</p><ul><li>In-app notification</li><li>Email (if you have provided one)</li></ul><p>We encourage you to review this policy periodically. Your continued use of Mikazuki AI after changes take effect constitutes your acceptance of the updated policy.</p><hr><h2 id="_11-contact-us" tabindex="-1">11. Contact Us <a class="header-anchor" href="#_11-contact-us" aria-label="Permalink to “11. Contact Us”">​</a></h2><p>If you have any questions, concerns, or requests regarding this Privacy Policy, please contact us:</p><ul><li><strong>Email:</strong> <a href="mailto:support@r8kstudio.net" target="_blank" rel="noreferrer">support@r8kstudio.net</a></li><li><strong>Developer:</strong> Rafiq8K Studio</li></ul><hr><p><em>This Privacy Policy was last updated on July 25, 2026.</em></p>`,62)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};